import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('accumulateUsage', () => {
  it('sums token fields when both operands are defined', () => {
    const a: UsageMetadata = {inputTokens: 10, outputTokens: 4, totalTokens: 14};
    const b: UsageMetadata = {inputTokens: 25, outputTokens: 8, totalTokens: 33};
    expect(accumulateUsage(a, b)).toEqual({inputTokens: 35, outputTokens: 12, totalTokens: 47});
  });

  it('returns the defined side when one operand is undefined', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });

  it('returns undefined when both operands are undefined', () => {
    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
  });
});
CHANGELOG.md:19:- **`afterModelResponse` now receives usage summed across every provider call in the turn, not only the final round.** For a turn that completed without tool calls the value is identical to before. For a turn that ran tool rounds, existing consumers will now record a larger number that covers the full cost of the turn — the increase is exactly what was previously uncounted. `undefined` is still passed when no round in the turn reported usage.
CHANGELOG.md:34:- `maxToolRounds` now counts executed rounds: the default of 5 runs 5 tool rounds, not 6. Raise it by one to keep the old count.
CHANGELOG.md:35:- Offering a bare access token as the only WebSocket subprotocol still works but is deprecated: offer `hal.v1` beside it now, because the next minor release stops accepting a bare token.
CHANGELOG.md:41:- `HalEngineConfig.transport` now accepts three optional extension points: `additionalRoutes` (mounts a router under `basePath`, unauthenticated), `rootRoutes` (mounts a router at `/`, after the `basePath` router and before the 404 catch-all), and `errorHandler` (replaces Express's default HTML error page). Pass none of them and the app is identical to before. See `docs/getting-started.md` for usage and the GDPR / NIS-2 notes that apply to unauthenticated routes.
CHANGELOG.md:42:- `OrchestratorHooks` gains an optional `beforeToolCall(session, call)` hook that fires before each known tool's executor, once per call per round. Return `undefined` to let the call run, or a `ToolResponse` to decline it: the executor is skipped and the model reads your `result` as that call's `tool_result`, with `clientMessages` and `suppressAssistantResponse` behaving as a tool's would. A hook that throws declines the call instead of failing the turn. Use it for an audit of what the model attempted or an EU AI Act Article 14 human-oversight control. The hook receives the model's raw tool input and, through `session`, the caller's `authHeaders`, so don't log either. Additive: with no hook installed, nothing changes.
CHANGELOG.md:43:- `OrchestratorHooks` gains an optional `onToolBudgetExhausted(session, budget)` hook, and `ToolBudgetInfo` (`{maxToolRounds, requestedTools}`) and `TOOL_BUDGET_EXHAUSTED` are exported. It fires when the model asks for a tool round `maxToolRounds` refuses, after the last provider call and before `afterModelResponse`. Return a sentence and the turn ends on it as an ordinary assistant entry, so the user sees a degraded answer instead of silence; the engine writes no prose of its own. Every exhausted run now also ends with a `{type: 'stop', stopReason: 'tool_budget_exhausted'}` chunk, a new value for the existing field rather than a new type, which the WebSocket transport sends nothing for. The turn still ends with `stream_end`, never `error`. Additive: with no hook installed, the wire is unchanged.
CHANGELOG.md:44:- `AssistantEntry` and `ThinkingEntry` gain an optional `truncated: true`, set on an entry the run could not finish: a provider failure mid-stream, or a round that ends on a tool call with no `stop`. The server re-sends such an entry as an `entry_upsert` carrying the flag just before its `entry_commit`, and the flag stays on the stored entry, so a client can render a cut-off answer as cut off live or on a replay, without relying on the transient `error` frame. An entry committed normally never carries it; a suppressed entry is flagged in the session but never re-sent. Text the thinking-tag parser was still holding back is now kept in a cut-off entry, as it already was on a normal stop. Additive: a client that ignores the field renders what it did before, and the extra `entry_upsert` replaces the entry with the content it already has.
CHANGELOG.md:49:- Every assistant and thinking entry a run opens is now committed when the run ends, however it ends: a provider that throws mid-stream, or a round that ends on a tool call with no `stop`, no longer leaves an entry with `isStreaming: true` in the session. The partial content is kept exactly as streamed, and on a throw its `entry_commit` arrives before the `error` frame. **Migration note**: `entry_commit` now arrives on paths that previously sent none, so a client counting commit frames sees more of them. No wire type changes, and a client that already stops streaming on `stream_end` renders the same result.
CHANGELOG.md:50:- `maxToolRounds` now bounds the tool rounds that are actually executed: at most `maxToolRounds` rounds run, and the provider is called at most `maxToolRounds + 1` times. Previously the loop ran one extra round whose tool results no provider call ever read, so the default of 5 executed 6 rounds; it now executes 5, and the sixth provider call still reads the fifth round's results. `maxToolRounds: 0` now means one provider call and no tool execution, a negative value behaves as 0, and a non-finite value falls back to the default. When the budget runs out, the engine logs one `warn` (`tool budget exhausted`) naming the tools it did not run. **Migration note**: no exported type or signature changes, but a tool with a side effect in that final, unread round no longer runs there; to restore the old count, raise `maxToolRounds` by one.
CHANGELOG.md:54:- `ToolRegistry.execute` now validates tool input against the declared `inputSchema` before invoking the executor. A schema-invalid call returns a descriptive `ToolResponse` to the model (naming the failing property path and constraint, never the value) rather than throwing, so the model can retry within the existing tool-round budget. Extra properties pass through to the executor unchanged. **Migration note**: an executor that previously hand-validated its own input now receives only input that has already passed the declared schema; a tool that relied on seeing malformed input to produce its own error message will no longer see it.
CHANGELOG.md:55:- The WebSocket server no longer echoes the access token in its handshake response. A client offers the new `hal.v1` marker beside its token (`new WebSocket(url, ['hal.v1', token])`, or `HAL_WS_SUBPROTOCOL`, now exported from the package root) and the server answers only `hal.v1`, so the token stays out of the 101 response headers and off the connected socket's `protocol` property. The token is read as the first offered value that is not the marker, in either order, and still reaches tools as `authHeaders.authorization`. `credentialFromSubprotocol`, also newly exported, reads it the same way for your own `WsAuthenticator`. **Migration note**: every client must be updated to offer `hal.v1` alongside its token, and an authenticator that took the first `Sec-WebSocket-Protocol` value as the token now gets `hal.v1` from an updated client, so read it with `credentialFromSubprotocol(req.headers['sec-websocket-protocol'])` instead. From the next MINOR, a client that offers only a bare token receives a 101 with no `Sec-WebSocket-Protocol` header, and `ws` and Chromium both fail such a handshake; this release still accepts a bare token (see Deprecated), because `0.2.x` documented it.
CHANGELOG.md:59:- Offering a bare access token as the only WebSocket subprotocol. This release still echoes it and logs a warning that never includes the offered value; the next MINOR stops echoing it, and a client that has not added `hal.v1` will then fail its handshake.
